package com.kitchenos.connect.kitchen;
import org.json.*;
/** Narrow read projection of Calomatik's existing sync entities. No body metrics or tracking history. */
public final class SharedAssistantProfile {
    private static String text(Object raw,int max){return raw instanceof String?((String)raw).trim().substring(0,Math.min(((String)raw).trim().length(),max)):"";}
    private static String list(Object raw){if(raw instanceof String)return text(raw,1000);if(!(raw instanceof JSONArray))return "";StringBuilder out=new StringBuilder();JSONArray values=(JSONArray)raw;for(int i=0;i<Math.min(20,values.length());i++){String value=text(values.opt(i),100);if(value.isEmpty())continue;if(out.length()>0)out.append(", ");out.append(value);}return out.substring(0,Math.min(1000,out.length()));}
    public static void apply(JSONObject records,JSONObject entity)throws Exception{
        String type=entity.optString("type"),id=entity.optString("id");if(!java.util.Arrays.asList("profile","assistantProfile","memory").contains(type)||id.length()>512||id.isEmpty())return;String key=type+":"+id;if(entity.optBoolean("deleted")){records.remove(key);return;}JSONObject source=entity.optJSONObject("data");if(source==null)return;JSONObject kept=new JSONObject();
        if(type.equals("profile")){for(String field:new String[]{"diet","allergies","dislikes","dietaryRestrictions"}){String value=list(source.opt(field));if(!value.isEmpty())kept.put(field,value);}}
        else if(type.equals("assistantProfile")){JSONObject preferences=source.optJSONObject("preferences"),communication=preferences==null?null:preferences.optJSONObject("communication");if(preferences!=null&&preferences.opt("remember") instanceof Boolean)kept.put("remember",preferences.getBoolean("remember"));if(communication!=null){JSONObject result=new JSONObject();for(String field:new String[]{"tone","humor"}){String value=text(communication.opt(field),40);if(!value.isEmpty())result.put(field,value);}if(communication.opt("emojis") instanceof Boolean)result.put("emojis",communication.getBoolean("emojis"));kept.put("communication",result);}}
        else{String status=source.optString("status"),basis=source.optString("basis"),scope=source.optString("scope");if(!java.util.Arrays.asList("active","confirmed").contains(status)||!java.util.Arrays.asList("user_stated","user_confirmed","user_edited","manual").contains(basis)||!java.util.Arrays.asList("general","home_cooking").contains(scope)){records.remove(key);return;}String expiry=source.optString("expiresOn");if(!expiry.isEmpty()&&expiry.compareTo(java.time.LocalDate.now().toString())<0){records.remove(key);return;}kept.put("text",text(source.opt("text"),600));}
        if(kept.length()>0){records.put(key,kept);trimMemories(records);}else records.remove(key);
    }
    private static void trimMemories(JSONObject records)throws JSONException{java.util.ArrayList<String> memories=new java.util.ArrayList<>();int settings=0;java.util.Iterator<String> keys=records.keys();while(keys.hasNext()){String key=keys.next();if(key.startsWith("memory:"))memories.add(key);else settings++;}if(settings>64)throw new JSONException("Zu viele Assistenteneinstellungen");while(memories.size()>64)records.remove(memories.remove(0));}
    public static JSONObject preferences(JSONObject records)throws Exception{JSONObject result=new JSONObject();boolean remember=false,known=false;java.util.Iterator<String> settings=records.keys();while(settings.hasNext()){JSONObject row=records.optJSONObject(settings.next());if(row!=null&&row.has("remember")){remember=known?remember&&row.optBoolean("remember"):row.optBoolean("remember");known=true;}}result.put("remember",remember).put("rememberKnown",known);StringBuilder notes=new StringBuilder();java.util.Iterator<String> keys=records.keys();while(keys.hasNext()){String key=keys.next();JSONObject row=records.optJSONObject(key);if(row==null)continue;for(String field:new String[]{"diet","allergies","dislikes"})if(row.has(field))result.put(field,row.optString(field));if(row.has("dietaryRestrictions"))notes.append("Ernährungshinweise aus Kalomatik: ").append(row.optString("dietaryRestrictions")).append('\n');if(row.has("communication"))notes.append("Gewählter Gesprächsstil in Kalomatik: ").append(row.getJSONObject("communication")).append('\n');if(remember&&row.has("text"))notes.append("Bestätigte Vorliebe aus Kalomatik: ").append(row.optString("text")).append('\n');}result.put("notes",notes.substring(0,Math.min(1800,notes.length())));return result;}
    private SharedAssistantProfile(){}
}
